project.scaffoldingCode:
public class Employee {
    // 1. Protected fields accessible by subclasses
    protected String id;
    protected String name;
    protected String department;
    protected double baseSalary;

    public Employee(String id, String name, String department, double baseSalary) {
        if (id == null || id.trim().isEmpty()) throw new IllegalArgumentException("ID cannot be empty.");
        if (name == null || name.trim().isEmpty()) throw new IllegalArgumentException("Name cannot be empty.");
        if (baseSalary < 2000.0) throw new IllegalArgumentException("Base salary below statutory minimum.");
        this.id = id.trim();
        this.name = name.trim();
        this.department = (department != null) ? department.trim() : "General";
        this.baseSalary = baseSalary;
    }

    // 2. Base bonus calculation (10%)
    public double calculateBonus() {
        return this.baseSalary * 0.10;
    }

    public void displayProfile() {
        System.out.println("-------------------------------------------------------");
        System.out.printf("Employee ID:   %s%n", id);
        System.out.printf("Name:          %s%n", name);
        System.out.printf("Department:    %s%n", department);
        System.out.printf("Base Salary:   $%.2f%n", baseSalary);
        System.out.printf("Base Bonus:    $%.2f%n", calculateBonus());
        System.out.println("-------------------------------------------------------");
    }

    public String getId() { return id; }
    public String getName() { return name; }
    public double getBaseSalary() { return baseSalary; }
}

// 3. Developer Subclass
class Developer extends Employee {
    private String primaryLanguage;
    private int certificationsCount;

    public Developer(String id, String name, double baseSalary, String primaryLanguage, int certificationsCount) {
        super(id, name, "Engineering", baseSalary); // Constructor chaining
        this.primaryLanguage = (primaryLanguage != null) ? primaryLanguage : "Java";
        this.certificationsCount = Math.max(0, certificationsCount);
    }

    @Override
    public double calculateBonus() {
        // Base 10% bonus + $500 per certification
        return super.calculateBonus() + (this.certificationsCount * 500.0);
    }

    @Override
    public void displayProfile() {
        System.out.println("=======================================================");
        System.out.println("               ROLE PROFILE: DEVELOPER                 ");
        System.out.println("=======================================================");
        System.out.printf("ID:            %s%n", id);
        System.out.printf("Name:          %s%n", name);
        System.out.printf("Department:    %s%n", department);
        System.out.printf("Language:      %s%n", primaryLanguage);
        System.out.printf("Certifications: %d%n", certificationsCount);
        System.out.printf("Base Salary:   $%.2f%n", baseSalary);
        System.out.printf("Total Bonus:   $%.2f (includes cert bonus)%n", calculateBonus());
        System.out.printf("Total Comp:    $%.2f%n", baseSalary + calculateBonus());
        System.out.println("=======================================================\n");
    }
}

// 4. Manager Subclass
class Manager extends Employee {
    protected int teamSize;

    public Manager(String id, String name, String department, double baseSalary, int teamSize) {
        super(id, name, department, baseSalary);
        this.teamSize = Math.max(0, teamSize);
    }

    @Override
    public double calculateBonus() {
        // Base 10% bonus + $250 per team member
        return super.calculateBonus() + (this.teamSize * 250.0);
    }

    @Override
    public void displayProfile() {
        System.out.println("=======================================================");
        System.out.println("               ROLE PROFILE: MANAGER                   ");
        System.out.println("=======================================================");
        System.out.printf("ID:            %s%n", id);
        System.out.printf("Name:          %s%n", name);
        System.out.printf("Department:    %s%n", department);
        System.out.printf("Team Size:     %d direct reports%n", teamSize);
        System.out.printf("Base Salary:   $%.2f%n", baseSalary);
        System.out.printf("Total Bonus:   $%.2f (includes team bonus)%n", calculateBonus());
        System.out.printf("Total Comp:    $%.2f%n", baseSalary + calculateBonus());
        System.out.println("=======================================================\n");
    }
}

// 5. Executive Subclass (Extends Manager)
class Executive extends Manager {
    private int stockOptions;

    public Executive(String id, String name, String department, double baseSalary, int teamSize, int stockOptions) {
        super(id, name, department, baseSalary, teamSize); // Chaining to Manager constructor
        this.stockOptions = Math.max(0, stockOptions);
    }

    @Override
    public double calculateBonus() {
        // Super bonus (from Manager: base 10% + team size) + $10 per stock option grant
        return super.calculateBonus() + (this.stockOptions * 10.0);
    }

    @Override
    public void displayProfile() {
        System.out.println("=======================================================");
        System.out.println("               ROLE PROFILE: EXECUTIVE                 ");
        System.out.println("=======================================================");
        System.out.printf("ID:            %s%n", id);
        System.out.printf("Name:          %s%n", name);
        System.out.printf("Department:    %s%n", department);
        System.out.printf("Managed Team:  %d reports%n", teamSize);
        System.out.printf("Stock Options: %d shares%n", stockOptions);
        System.out.printf("Base Salary:   $%.2f%n", baseSalary);
        System.out.printf("Total Bonus:   $%.2f (includes team & equity)%n", calculateBonus());
        System.out.printf("Total Comp:    $%.2f%n", baseSalary + calculateBonus());
        System.out.println("=======================================================\n");
    }
}

